#!/bin/sh
# Asterism installer for macOS and Linux, generated by the Asterism server named below.
#
#   curl -fsSL <server>/install.sh | sh -s -- <agent invitation link> [--name <name>]
#
# It picks the build for this system and processor, downloads it from the server's /dl/ (unless the same
# build is installed already), checks its SHA-256 against the server's manifest, puts it in
# ~/.asterism/bin/asterism and runs `asterism join` with the arguments it was given.
# POSIX sh only: no bash features.
#
# Everything is inside main(), called on the last line, so a download cut short runs nothing.

ASTERISM_URL=@ASTERISM_URL@

main() {
    set -eu

    say() { printf 'asterism install: %s\n' "$1" >&2; }
    fail() { say "$1"; exit 1; }

    if [ -z "${HOME:-}" ]; then
        fail "HOME is not set, so there is no place for ~/.asterism."
    fi

    # The build for this system and processor: <system>-<processor>, as the manifest names it.
    case "$(uname -s)" in
        Linux) os=linux ;;
        Darwin) os=macos ;;
        *) fail "this system ($(uname -s)) has no build; use macOS, Linux or Windows." ;;
    esac
    case "$(uname -m)" in
        x86_64 | amd64) arch=x64 ;;
        arm64 | aarch64) arch=arm64 ;;
        *) fail "this processor ($(uname -m)) has no build; x64 and arm64 do." ;;
    esac
    # A shell running under Rosetta on Apple silicon reports x86_64; take the native build.
    if [ "$os" = macos ] && [ "$arch" = x64 ] \
        && [ "$(sysctl -n sysctl.proc_translated 2>/dev/null || true)" = 1 ]; then
        arch=arm64
    fi
    key="$os-$arch"

    if command -v curl >/dev/null 2>&1; then
        fetch() { curl -fsSL --retry 2 -o "$2" "$1"; }
    elif command -v wget >/dev/null 2>&1; then
        fetch() { wget -q -O "$2" "$1"; }
    else
        fail "neither curl nor wget is installed."
    fi

    if command -v sha256sum >/dev/null 2>&1; then
        sha256_of() { sha256sum "$1" | cut -d ' ' -f 1; }
    elif command -v shasum >/dev/null 2>&1; then
        sha256_of() { shasum -a 256 "$1" | cut -d ' ' -f 1; }
    elif command -v openssl >/dev/null 2>&1; then
        sha256_of() { openssl dgst -sha256 -r "$1" | cut -d ' ' -f 1; }
    else
        fail "none of sha256sum, shasum or openssl is installed, so the download cannot be checked."
    fi

    bin_dir="${ASTERISM_HOME:-$HOME/.asterism}/bin"      # where the program itself keeps its state
    target="$bin_dir/asterism"
    mkdir -p "$bin_dir"
    part="$bin_dir/.asterism.part.$$"
    manifest_file="$bin_dir/.manifest.part.$$"
    trap 'rm -f "$part" "$manifest_file"' EXIT
    trap 'exit 1' HUP INT TERM

    # The manifest is the server's own JSON: "files" maps each key to a flat object with "name" and "sha256".
    if ! fetch "$ASTERISM_URL/dl/manifest.json" "$manifest_file"; then
        fail "could not read $ASTERISM_URL/dl/manifest.json."
    fi
    manifest=$(tr -d '\r\n' <"$manifest_file")
    entry=$(printf '%s' "$manifest" | sed -n "s/.*\"$key\"[[:space:]]*:[[:space:]]*{\([^}]*\)}.*/\1/p")
    if [ -z "$entry" ]; then
        fail "the server has no build for $key yet."
    fi
    field() { printf '%s' "$entry" | sed -n "s/.*\"$1\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p"; }
    name=$(field name)
    sum=$(field sha256 | tr 'A-F' 'a-f')
    case "$name" in
        "" | .* | */* | *[!A-Za-z0-9._-]*) fail "the manifest names the build oddly ($name)." ;;
    esac
    case "$sum" in
        *[!0-9a-f]*) fail "the manifest's SHA-256 for $key is not a hash." ;;
    esac
    if [ "${#sum}" -ne 64 ]; then
        fail "the manifest's SHA-256 for $key is not a hash."
    fi

    if [ -f "$target" ] && [ "$(sha256_of "$target")" = "$sum" ]; then
        say "the current build is installed already: $target"
    else
        say "downloading $name"
        if ! fetch "$ASTERISM_URL/dl/$name" "$part"; then
            fail "could not download $ASTERISM_URL/dl/$name."
        fi
        got=$(sha256_of "$part")
        if [ "$got" != "$sum" ]; then
            fail "the download does not match the manifest (SHA-256 $got, expected $sum); nothing was installed."
        fi
        chmod 755 "$part"
        # Same directory, so the rename is atomic; a running copy keeps its old file until it exits.
        mv -f "$part" "$target"
        say "installed $target"
    fi

    # exec skips the EXIT trap: clean up first.
    rm -f "$manifest_file"
    trap - EXIT HUP INT TERM
    exec "$target" join "$@"
}

main "$@"
